"""Ingest UTF-8 Python sources from a folder of repositories."""

from __future__ import annotations

from collections.abc import Iterator
from pathlib import Path

from toklab.core.hashing import sha256_text
from toklab.core.types import SourceFile

MAX_FILE_BYTES = 1_048_576  # 1 MiB
SKIP_DIR_NAMES = frozenset({"vendor", "build", "site-packages"})
GENERATED_MARKERS = (
    "@generated",
    "auto-generated",
    "automatically generated",
    "do not edit",
    "generated by",
)


def _is_under_skipped_dir(rel: Path) -> bool:
    return any(part in SKIP_DIR_NAMES for part in rel.parts)


def _looks_generated(path: Path, text: str) -> bool:
    if "generated" in path.name.lower():
        return True
    head = "\n".join(text.splitlines()[:40]).lower()
    return any(marker in head for marker in GENERATED_MARKERS)


def _read_utf8_text(path: Path) -> str | None:
    """Return decoded text, or None if binary / not valid UTF-8."""
    raw = path.read_bytes()
    if b"\x00" in raw:
        return None
    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        return None


def ingest_repos(repos_dir: Path | str) -> Iterator[SourceFile]:
    """Yield SourceFile records for eligible ``.py`` files under ``repos_dir``.

    Each immediate child directory of ``repos_dir`` is treated as one
    repository. Originals are never modified. Files are skipped when they
    exceed 1 MiB, are not valid UTF-8, live under vendor/build/site-packages,
    or carry generated-file markers.
    """
    root = Path(repos_dir)
    if not root.is_dir():
        raise FileNotFoundError(f"repos directory not found: {root}")

    repo_dirs = sorted(
        p for p in root.iterdir() if p.is_dir() and not p.name.startswith(".")
    )
    for repo_dir in repo_dirs:
        repo = repo_dir.name
        for path in sorted(repo_dir.rglob("*.py")):
            if not path.is_file():
                continue
            rel = path.relative_to(repo_dir)
            if _is_under_skipped_dir(rel):
                continue
            n_bytes = path.stat().st_size
            if n_bytes > MAX_FILE_BYTES:
                continue
            text = _read_utf8_text(path)
            if text is None:
                continue
            if _looks_generated(path, text):
                continue
            digest = sha256_text(text)
            file_id = sha256_text(f"{repo}:{rel.as_posix()}")
            yield SourceFile(
                file_id=file_id,
                repo=repo,
                path=rel.as_posix(),
                sha256=digest,
                language="python",
                n_bytes=n_bytes,
                split="",
            )
